(* [comment removed for export] *)
Definition etail (p c0 : Z) : Prop :=
  (c0 = 0 /\ p = Z.of_nat (length bz) - 1)%Z \/
  (c0 = 101 /\ exists (bsg b0 : byte) (ne : nat), nth_error bz (Z.to_nat (p + 1)) = Some bsg /\ (bv_unsigned bsg = 43 \/ bv_unsigned bsg = 45)
                /\ (1 <= ne)%nat /\ digs_at bz (p + 2) ne /\ nth_error bz (Z.to_nat (p + 2) + ne)%nat = Some b0 /\ bv_unsigned b0 = 0
                /\ p + 2 + Z.of_nat ne = Z.of_nat (length bz) - 1)%Z.

(* [comment removed for export] *)
Definition gdigits (p : Z) (gr : Z) : Prop :=
  exists n1 : nat, digs_at bz (p + 1) n1 /\
   ((exists b0 : byte, nth_error bz (Z.to_nat (p + 1) + n1)%nat = Some b0 /\ ~ isdg (bv_unsigned b0) /\ bv_unsigned b0 <> 46 /\ etail (p + 1 + Z.of_nat n1) (bv_unsigned b0)
       /\ (p + 1 + Z.of_nat n1 <= 26)%Z)
    \/ (gr = 0 /\ (exists bd : byte, nth_error bz (Z.to_nat (p + 1) + n1)%nat = Some bd /\ bv_unsigned bd = 46) /\
        exists (n2 : nat) (b0 : byte), (1 <= n2)%nat /\ digs_at bz (p + 2 + Z.of_nat n1) n2 /\ nth_error bz (Z.to_nat (p + 2 + Z.of_nat n1) + n2)%nat = Some b0
          /\ ~ isdg (bv_unsigned b0) /\ bv_unsigned b0 <> 46 /\ etail (p + 2 + Z.of_nat n1 + Z.of_nat n2) (bv_unsigned b0) /\ (p + 2 + Z.of_nat n1 + Z.of_nat n2 <= 26)%Z))%Z.


Definition gstart (p c gr gd : Z) : Prop := (isdg c /\ c <> 48 /\ gdigits p gr)%Z \/ (~ isdg c /\ gd = 1 /\ etail p c)%Z.


(* [comment removed for export] *)
Definition xinv (xs : list word) (k j dc lnz : Z) : Prop :=
  exists w0 wk : word, nth_error xs 0 = Some w0 /\ nth_error xs (Z.to_nat k) = Some wk
  /\ (0 <= k <= 2)%Z /\ (0 <= j <= 8)%Z /\ (dc = 9 * k + j)%Z /\ (0 <= lnz <= dc)%Z
  /\ (dc = 0 -> bv_unsigned w0 = 0)%Z /\ (1 <= dc -> 1 <= lnz)%Z
  /\ (1 <= dc -> k = 0 -> 10 ^ (j - 1) <= bv_unsigned w0 < 10 ^ j)%Z /\ (1 <= k -> 100000000 <= bv_unsigned w0 < 1000000000)%Z
  /\ (1 <= j -> bv_unsigned wk < 10 ^ j)%Z.

