Lemma sc_body : forall (ra t0 t1 t2 a3 a4 a5 a6 a7 s2 s3 s4 s9 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : word -> option byte) (j0 : list byte) (v8 v16 v24 v32 v40 v48 v56 v64 v72 v80 v88 : word) (xs : list word) (k j dc lnz c : Z),
  mem_inv rsegs m ->
  rw_cells rsegs m spz [CB 8 j0; C8 v8; C8 v16; C8 v24; C8 v32; C8 v40; C8 v48; C8 v56; C8 v64; C8 v72; C8 v80; C8 v88; C8 (Z_to_bv 64 lnz)] ->
  u32arr rsegs m (spz + 104) xs ->
  length xs = 2048%nat ->
  w32 xs ->
  isdg c ->
  (dc = 0 -> c <> 48)%Z ->
  (dc + 1 <= 26)%Z ->
  xinv xs k j dc lnz ->
  evt rsegs (fun ms' => exists (k' j' lnz' v : Z) (a0' a1' a2' a3' : word) (m' : word -> option byte),
      ms' = MS (mkR ra (Z_to_bv 64 spz) gp tp t0 t1 t2 (Z_to_bv 64 48) (Z_to_bv 64 (dc + 1)) a0' a1' a2' a3' a4 a5 a6 a7 s2 (Z_to_bv 64 1) s4 (Z_to_bv 64 (spz + 8416)) (Z_to_bv 64 10) (Z_to_bv 64 46) (Z_to_bv 64 k') s9 (Z_to_bv 64 j') (Z_to_bv 64 2044) t3 t4 t5 t6) F
               (Z_to_bv 64 0x144370) fc None m' (seg_rom rsegs)
      /\ munch [(spz + 96, spz + 8296)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ rw_cells rsegs m' spz [CB 8 j0; C8 v8; C8 v16; C8 v24; C8 v32; C8 v40; C8 v48; C8 v56; C8 v64; C8 v72; C8 v80; C8 v88; C8 (Z_to_bv 64 lnz')]
      /\ u32arr rsegs m' (spz + 104) (upd xs (Z.to_nat k) (Z_to_bv 64 v)) /\ xinv (upd xs (Z.to_nat k) (Z_to_bv 64 v)) k' j' (dc + 1) lnz' /\ (0 <= v < 2 ^ 32)%Z) (MS (mkR ra (Z_to_bv 64 spz) gp tp t0 t1 t2 (Z_to_bv 64 48) (Z_to_bv 64 dc) (Z_to_bv 64 c) (Z_to_bv 64 (bv_swrap 32 (c + -48))) (Z_to_bv 64 0) a3 a4 a5 a6 a7 s2 s3 s4 (Z_to_bv 64 (spz + 8416)) (Z_to_bv 64 10) (Z_to_bv 64 46) (Z_to_bv 64 k) s9 (Z_to_bv 64 j) (Z_to_bv 64 2044) t3 t4 t5 t6) F (Z_to_bv 64 0x1442ec) fc None m (seg_rom rsegs)).
