Lemma sc_lz1 : forall (n : nat) (ra t0 t1 t2 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : word -> option byte) (i : Z) (b1 : byte),
  mem_inv rsegs m -> u8ro rsegs m s bz ->
  rw_cells rsegs m (spz + 8424) [C8 (Z_to_bv 64 (s + i))] -> rw_cells rsegs m (spz + 8600) [C8 (Z_to_bv 64 18446744073709551615); C8 (Z_to_bv 64 0)] ->
  (0 <= i)%Z -> zeros_at i n -> nth_error bz (Z.to_nat i + n)%nat = Some b1 -> (bv_unsigned b1 <> 48)%Z ->
  evt rsegs (fun ms' => exists (a1' : word) m',
      ms' = MS (mkR ra (Z_to_bv 64 spz) gp tp t0 t1 t2 (Z_to_bv 64 48) s1 (Z_to_bv 64 (bv_unsigned b1)) a1' a2 a3 a4 a5 a6 a7 s2 s3 s4 (Z_to_bv 64 (spz + 8416)) s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F
               (Z_to_bv 64 0x144148) fc None m' (seg_rom rsegs)
      /\ munch [(spz + 8424, spz + 8432)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ rw_cells rsegs m' (spz + 8424) [C8 (Z_to_bv 64 (s + i + Z.of_nat n + 1))])
    (MS (mkR ra (Z_to_bv 64 spz) gp tp t0 t1 t2 (Z_to_bv 64 48) s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 (Z_to_bv 64 (spz + 8416)) s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F
        (Z_to_bv 64 0x14412c) fc None m (seg_rom rsegs)).
Proof.
