Definition gafterz (p c : Z) : Prop :=
  (isdg c /\ c <> 48 /\ gdigits p 0)%Z \/ (~ isdg c /\ c <> 46 /\ etail p c)%Z \/
  (c = 46 /\ exists (z2 : nat) (bw : byte), zeros_at (p + 1) z2 /\ nth_error bz (Z.to_nat (p + 1) + z2)%nat = Some bw /\ bv_unsigned bw <> 48 /\ (Z.of_nat z2 <= 28)%Z /\
     ((isdg (bv_unsigned bw) /\ gdigits (p + 1 + Z.of_nat z2) 1) \/ (~ isdg (bv_unsigned bw) /\ etail (p + 1 + Z.of_nat z2) (bv_unsigned bw))))%Z.

Lemma sc_numB0 : forall (ra t0 t1 t2 s1 a1 a2 a3 a4 a5 a6 a7 s9 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : word -> option byte) (j0 : list byte) (v8 v16 v24 v32 v40 v48 v56 v64 v72 v80 v88 v96 ev : word) (xs : list word) (p c : Z),
  mem_inv rsegs m ->
  stk rsegs m lo spz ->
  rw_cells rsegs m spz [CB 8 j0; C8 v8; C8 v16; C8 v24; C8 v32; C8 v40; C8 v48; C8 v56; C8 v64; C8 v72; C8 v80; C8 v88; C8 v96] ->
  u32arr rsegs m (spz + 104) xs ->
  length xs = 2048%nat ->
  w32 xs ->
  rw_cells rsegs m (spz + 8296) [C8 G; C8 fs0o; C8 s11o; C8 s10o; C8 s9o; C8 s8o; C8 s7o; C8 s6o; C8 s5o; C8 s4o; C8 s3o; C8 s2o; C8 s1o; C8 s0o; C8 ra0] ->
  ro_cells rsegs m 7027520 [C8 G] ->
  rw_cells rsegs m (bv_unsigned tp + -164) [C4 ev] ->
  fkl fcs_no8 F0 F ->
  frm0 fc ->
  munch W2 m0 m ->
  wmono rsegs m0 m ->
  rw_cells rsegs m (spz + 8424) [C8 (Z_to_bv 64 (s + p + 1))] ->
  rw_cells rsegs m (spz + 8600) [C8 (Z_to_bv 64 18446744073709551615); C8 (Z_to_bv 64 0)] ->
  u8ro rsegs m s bz ->
  (0 <= p)%Z ->
  (0 <= c < 256)%Z ->
