Definition gnum0 (p c : Z) : Prop :=
  (c <> 48 /\ isdg c /\ gdigits p 0)%Z \/
  (c = 48 /\ exists (z : nat) (b1 bz1 : byte), nth_error bz (Z.to_nat (p + 1)) = Some b1 /\ Z.land (bv_unsigned b1) 18446744073709551583 <> 88 /\ zeros_at (p + 1) z /\ (Z.of_nat z <= 27)%Z
